public static void tick(LevelTickEvent.Post event) {
		if (!(event.getLevel() instanceof ServerLevel serverLevel)) {
			return;
		}

		ResourceKey<Level> dim = serverLevel.dimension();
		if (!worldStorageSoundInfos.containsKey(dim)) {
			return;
		}

		removeFinished(serverLevel, dim);

		if (lastWorldCheck.computeIfAbsent(dim, key -> serverLevel.getGameTime()) > serverLevel.getGameTime() - KEEP_ALIVE_CHECK_INTERVAL) {
			return;
		}
		lastWorldCheck.put(dim, serverLevel.getGameTime());

		worldStorageSoundInfos.get(dim).entrySet().removeIf(entry -> {
			if (entry.getValue().getLastKeepAliveTime() < serverLevel.getGameTime() - KEEP_ALIVE_CHECK_INTERVAL) {
				sendStopMessage(serverLevel, entry.getValue().getLastPosition(), entry.getKey());
				return true;
			}
			return false;
		});
	}

@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		if (!level.isClientSide()) {
			if (!discsRemoved.isEmpty()) {
				discsRemoved.forEach(index -> {
					playlist.remove(index);
					history.remove(index);
				});
				discsRemoved.clear();
			}
			if (!discsAdded.isEmpty()) {
				playlist.addAll(discsAdded);
				discsAdded.clear();
			}
		}

		if (isPlaying && lastKeepAliveSendTime < level.getGameTime() - KEEP_ALIVE_SEND_INTERVAL) {
			Vec3 soundPosition = entityPlaying != null
					? entityPlaying.position()
					: posPlaying != null ? Vec3.atCenterOf(posPlaying) : entity != null ? entity.position() : Vec3.atCenterOf(pos);
			storageWrapper.getContentsUuid()
					.ifPresent(storageUuid -> ServerStorageSoundHandler.updateKeepAlive(storageUuid, level, soundPosition, () -> setIsPlaying(false)));
			lastKeepAliveSendTime = level.getGameTime();
		}
	}

private static void removeFinished(ServerLevel serverLevel, ResourceKey<Level> dim) {
		List<UUID> storageIdsToRemove = new ArrayList<>();
		worldStorageSoundInfos.get(dim).forEach((storageId, soundInfo) -> {
			if (soundInfo.getFinishTime() <= serverLevel.getGameTime()) {
				storageIdsToRemove.add(storageId);
			}
		});
		storageIdsToRemove.forEach(storageId -> removeSoundInfo(serverLevel, storageId, true));
	}

public static void updateKeepAlive(UUID storageUuid, Level level, Vec3 position, Runnable onNoLongerRunning) {
		ResourceKey<Level> dim = level.dimension();
		if (!worldStorageSoundInfos.containsKey(dim) || !worldStorageSoundInfos.get(dim).containsKey(storageUuid)) {
			onNoLongerRunning.run();
			return;
		}
		if (worldStorageSoundInfos.get(dim).containsKey(storageUuid)) {
			worldStorageSoundInfos.get(dim).get(storageUuid).update(level.getGameTime(), position);
		}
	}

public static void putSoundInfo(ServerLevel serverLevel, UUID storageUuid, Runnable onFinishedHandler, Vec3 pos, long finishTime) {
		worldStorageSoundInfos.computeIfAbsent(serverLevel.dimension(), dim -> new HashMap<>()).put(storageUuid,
				new SoundInfo(onFinishedHandler, serverLevel.getGameTime(), pos, finishTime));
	}

private static void removeSoundInfo(Level level, UUID storageUuid, boolean finished) {
		ResourceKey<Level> dim = level.dimension();
		if (worldStorageSoundInfos.containsKey(dim) && worldStorageSoundInfos.get(dim).containsKey(storageUuid)) {
			SoundInfo soundInfo = worldStorageSoundInfos.get(dim).remove(storageUuid);
			if (finished) {
				soundInfo.runOnFinished();
			}
		}
	}

private static void sendStopMessage(Level level, Vec3 position, UUID storageUuid) {
		if (level instanceof ServerLevel serverLevel) {
			PacketDistributor.sendToPlayersNear(serverLevel, null, position.x(), position.y(), position.z(), 128, new StopDiscPlaybackPayload(storageUuid));
		}
	}

@SuppressWarnings({"unused", "java:S1172"}) // needs to be here for addListener to recognize which event this method should be subscribed to
	public static void onWorldUnload(LevelEvent.Unload evt) {
		if (!(evt.getLevel() instanceof ServerLevel serverLevel)) {
			return;
		}

		worldStorageSoundInfos.remove(serverLevel.dimension());
		lastWorldCheck.remove(serverLevel.dimension());
	}

private void playDisc() {
		Level level = entityPlaying != null ? entityPlaying.level() : levelPlaying;
		if (!(level instanceof ServerLevel serverLevel) || (posPlaying == null && entityPlaying == null)) {
			return;
		}
		ItemStack disc = getDisc();
		if (disc.isEmpty()) {
			return;
		}

		storageWrapper.getContentsUuid().ifPresent(storageUuid -> DiscHandlerRegistry.findHandler(disc).ifPresent(handler -> {
			if (entityPlaying != null) {
				handler.playDisc(serverLevel, entityPlaying.position(), storageUuid, disc, entityPlaying.getId(), onFinishedCallback);
			} else {
				handler.playDisc(serverLevel, posPlaying, storageUuid, disc, onFinishedCallback);
			}
			handler.getMusicLengthInTicks(disc, level)
					.ifPresent(lengthInTicks -> upgrade.set(ModCoreDataComponents.DISC_FINISH_TIME, level.getGameTime() + lengthInTicks));
		}));
		setIsPlaying(true);
	}

private void onDiscFinished() {
		if (getRepeatMode() == RepeatMode.ONE) {
			playDisc();
		} else if (getRepeatMode() == RepeatMode.ALL) {
			playNext();
		} else {
			playNext(false);
		}
	}

public void stop(LivingEntity entity) {
		if (!(entity.level() instanceof ServerLevel)) {
			return;
		}
		Level soundLevel = entityPlaying != null ? entityPlaying.level() : levelPlaying != null ? levelPlaying : entity.level();
		Vec3 soundPosition = entityPlaying != null ? entityPlaying.position() : posPlaying != null ? Vec3.atCenterOf(posPlaying) : entity.position();
		storageWrapper.getContentsUuid().ifPresent(storageUuid -> ServerStorageSoundHandler.stopPlayingDisc(soundLevel, soundPosition, storageUuid));
		setIsPlaying(false);
		upgrade.remove(ModCoreDataComponents.DISC_FINISH_TIME);
		setDiscSlotActive(-1);
		playlist.clear();
		history.clear();
	}

public static void playStorageSound(UUID storageUuid, SoundInstance sound) {
		stopStorageSound(storageUuid);
		storageSounds.put(storageUuid, sound);
		Minecraft.getInstance().getSoundManager().play(sound);
	}

public static void handlePayload(PlayDiscPayload payload, IPayloadContext context) {
		SoundEvent soundEvent = payload.song().value().soundEvent().value();
		if (payload.blockStorage) {
			StorageSoundHandler.playStorageSound(soundEvent, payload.storageUuid, payload.pos);
		} else {
			StorageSoundHandler.playStorageSound(soundEvent, payload.storageUuid, payload.entityId);
		}
	}

@Override
	public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
		if (state.getValue(VANISHED)) {
			if (state.getValue(ACTIVE)) {
				level.setBlockAndUpdate(pos, state.setValue(VANISHED, false).setValue(ACTIVE, false));
			} else {
				this.changeToActiveBlock(level, pos, state);
			}
			this.playReappearSound(level, pos);
		} else {
			if (state.getValue(ACTIVE)) {
				level.setBlockAndUpdate(pos, state.setValue(VANISHED, true).setValue(ACTIVE, false));
				level.scheduleTick(pos, this, 80);

				this.playVanishSound(level, pos);

				this.vanishParticles(level, pos);

				// activate all adjacent inactive doors
				for (Direction e : Direction.values()) {
					this.checkAndActivateCastleDoor(level, pos.relative(e));
				}
			}
		}
	}

@Override
    public void tick(BlockState pState, ServerLevel pLevel, BlockPos pPos, RandomSource pRandom) {
        if (pState.getValue(VANISHED)) {
            if (pState.getValue(ACTIVE)) {
                pLevel.setBlockAndUpdate(pPos, pState.setValue(VANISHED, false).setValue(ACTIVE, false));
            } else {
                this.changeToActiveBlock(pLevel, pPos, pState);
            }
            this.playReappearSound(pLevel, pPos);
        } else {
            if (pState.getValue(ACTIVE)) {
                pLevel.setBlockAndUpdate(pPos, pState.setValue(VANISHED, true).setValue(ACTIVE, false));
                pLevel.scheduleTick(pPos, this, 80);
                this.playVanishSound(pLevel, pPos);
                this.vanishParticles(pLevel, pPos);
                for (Direction direction : Direction.values()) {
                    this.checkAndActivateCastleDoor(pLevel, pPos.relative(direction));
                }
            }
        }
    }

@Override
	public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
		if (this.isVanished(state)) {
			if (state.getValue(ACTIVE)) {
				level.setBlockAndUpdate(pos, state.setValue(VANISHED, false).setValue(ACTIVE, false));
				level.playSound(null, pos, TFSounds.REAPPEAR_BLOCK.get(), SoundSource.BLOCKS, 0.3F, 0.3F);
			} else {
				level.playSound(null, pos, TFSounds.REAPPEAR_POOF.get(), SoundSource.BLOCKS, 0.3F, 0.5F);
				level.setBlockAndUpdate(pos, state.setValue(ACTIVE, true));
				level.scheduleTick(pos, this, 15);
			}
		} else {
			if (state.getValue(ACTIVE)) {
				if (state.hasProperty(VANISHED)) {
					level.setBlockAndUpdate(pos, state.setValue(ACTIVE, false).setValue(VANISHED, true));
					level.scheduleTick(pos, this, 80);
				} else {
					level.removeBlock(pos, false);
				}

				level.playSound(null, pos, state.getBlock() == TFBlocks.REAPPEARING_BLOCK.get() ? TFSounds.REAPPEAR_POOF.get() : TFSounds.VANISHING_BLOCK.get(), SoundSource.BLOCKS, 0.3F, 0.5F);

				for (Direction e : Direction.values()) {
					this.activate(level, pos.relative(e));
				}
			}
		}
	}

private InteractionResult onActivation(Level level, BlockPos pos, BlockState state) {
		if (state.getValue(VANISHED) || state.getValue(ACTIVE)) return InteractionResult.FAIL;

		if (isBlockLocked(level, pos)) {
			level.playSound(null, pos, TFSounds.DOOR_ACTIVATED.get(), SoundSource.BLOCKS, 1.0F, 0.3F);
			return InteractionResult.PASS;
		} else {
			changeToActiveBlock(level, pos, state);
			return InteractionResult.SUCCESS;
		}
	}

private void changeToActiveBlock(Level level, BlockPos pos, BlockState originState) {
		if (originState.getBlock() instanceof CastleDoorBlock) {
			level.setBlockAndUpdate(pos, originState.setValue(ACTIVE, true));
		}
		level.scheduleTick(pos, originState.getBlock(), 2 + level.getRandom().nextInt(5));
	}

public void checkAndActivateCastleDoor(Level level, BlockPos pos) {
		BlockState state = level.getBlockState(pos);

		if (state.getBlock() instanceof CastleDoorBlock && !state.getValue(VANISHED) && !state.getValue(ACTIVE) && !isBlockLocked(level, pos)) {
			this.changeToActiveBlock(level, pos, state);
		}
	}

private void vanishParticles(Level level, BlockPos pos) {
		if (level instanceof ServerLevel serverLevel) {
			RandomSource rand = level.getRandom();
			ParticlePacket particlePacket = new ParticlePacket();
			for (int dx = 0; dx < 4; ++dx) {
				for (int dy = 0; dy < 4; ++dy) {
					for (int dz = 0; dz < 4; ++dz) {
						particlePacket.queueParticle(TFParticleType.ANNIHILATE.get(), false, false,
							pos.getX() + (dx + 0.5D) / 4,
							pos.getY() + (dy + 0.5D) / 4,
							pos.getZ() + (dz + 0.5D) / 4,
							rand.nextGaussian() * 0.2D, rand.nextGaussian() * 0.2D, rand.nextGaussian() * 0.2D);
					}
				}
			}
			PacketDistributor.sendToPlayersNear(serverLevel, null, pos.getX(), pos.getY(), pos.getZ(), 32.0, particlePacket);
		}
	}

@Override
	public void onUpdate() {
		// super.onUpdate();
		if (!getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime() % 5 == 0) {
			if (!getHasExploded())
				checkArea();
			if (getHasExploded())
				checkAreaOfEffect();
		}

		if (!getEntityWorld().isRemote) {
			if (!getSwelling() && getSwellCount() > MIN_SWELL)
				setSwellCount(getSwellCount() - 1);

			if (getSwelling() && getSwellCount() < MAX_SWELL)
				setSwellCount(getSwellCount() + 1);

			if(getHasExploded()) {
				if (getSwellCount() < MAX_SWELL)
					setSwellCount(MAX_SWELL);
				if (getAOESizeXZ() > 0.5F)
					setAOESizeXZ(getAOESizeXZ() - 0.01F);
				if (getAOESizeXZ() <= 0.5F)
					setDead();
			}
		}

		if (getHasExploded())
			setBoundingBoxSize();

		if (getEntityWorld().isRemote)
			if(getHasExploded())
				spawnCloudParticle();
	}

@Override
	@Nullable
	protected Entity checkArea() {
		Entity entity = null;
		if (!getEntityWorld().isRemote && getEntityWorld().getDifficulty() != EnumDifficulty.PEACEFUL) {
			List<EntityPlayer> list = getEntityWorld().getEntitiesWithinAABB(EntityPlayer.class, proximityBox());
			for (int entityCount = 0; entityCount < list.size(); entityCount++) {
				entity = list.get(entityCount);

				if (entity != null) {
					if (entity instanceof EntityPlayer && !((EntityPlayer) entity).isSpectator() && !((EntityPlayer) entity).isCreative()) {
						if (canSneakPast() && entity.isSneaking())
							return null;
						else if (checkSight() && !canEntityBeSeen(entity))
							return null;
						else {
							if(!getSwelling())
								setSwelling(true);
						}
						if (!isDead && isSingleUse() && getSwellCount() >= MAX_SWELL) {
							explode();
						}
					}
				}
			}
			if (entity == null) {
				if (getSwelling())
					setSwelling(false);
			}
		}
		return entity;
	}

