@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		if (level.isClientSide() || nextCheckTime > level.getGameTime()) {
			return;
		}

		if (remainingApplyTime > 0) {
			remainingApplyTime--;
			if (remainingApplyTime <= 0) {
				if (defBeingApplied.hasItemUseEffects()) {
					triggerItemUseEffects(level);
				}
				applying = false;
				ItemStack remainingStack = defBeingApplied.finishUsing.apply(stackBeingAplied, applyingToEntity);
				stackBeingAplied = ItemStack.EMPTY;
				applyingToEntity = null;
				defBeingApplied = null;
				storageWrapper.getInventoryForUpgradeProcessing().insertItem(remainingStack, false);
				nextCheckTime = level.getGameTime() + CHECK_INTERVAL;
			} else if (shouldTriggerItemUseEffects()) {
				triggerItemUseEffects(level);
			}
			return;
		}

		if (entity instanceof LivingEntity livingEntity) {
			applyTo(livingEntity);
		} else {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, new AABB(pos).inflate(CHECK_RADIUS), this::entityMatches);
			for (LivingEntity livingEntity : entities) {
				applyTo(livingEntity);
				if (applying) {
					break;
				}
			}
		}
		if (!applying) {
			nextCheckTime = level.getGameTime() + CHECK_INTERVAL;
		}
	}

private void applyTo(LivingEntity livingEntity) {
		for (AlchemyFilterAttribute filterAttribute : getFilterAttributes()) {
			if (!filterAttribute.filter().isEmpty() && filterAttribute.condition().test(livingEntity, filterAttribute.value())) {
				itemDefinitions.stream().filter(def -> def.filter.test(filterAttribute.filter())).findFirst().ifPresent(def -> {
					if (def.canApply.test(livingEntity, filterAttribute.filter(), shouldMatchAllEffects(), shouldMatchEffectAmplifier())) {
						InventoryHelper.iterate(storageWrapper.getInventoryForUpgradeProcessing(), (slot, stack) -> {
							if (def.filter().test(stack) && def.stackMatches.test(stack, filterAttribute.filter(), shouldMatchAllEffects(),
									shouldMatchEffectDuration(), shouldMatchEffectAmplifier())) {
								remainingApplyTime = def.startUsing.applyAsInt(stack, livingEntity);
								if (remainingApplyTime > 0) {
									applying = true;
									stackBeingAplied = stack.copyWithCount(1);
									defBeingApplied = def;
									applyingToEntity = livingEntity;
								}
								stack.shrink(1);
								storageWrapper.getInventoryForUpgradeProcessing().setStackInSlot(slot, stack);
							}
						}, () -> applying);
					}
				});
			}
		}
	}

public void triggerItemUseEffects(Level level) {
		if (stackBeingAplied.getUseAnimation() == UseAnim.DRINK) {
			level.playSound(null, applyingToEntity.getX(), applyingToEntity.getY(), applyingToEntity.getZ(), stackBeingAplied.getDrinkingSound(),
					applyingToEntity.getSoundSource(), 0.5F, level.random.nextFloat() * 0.1F + 0.9F);
		}

		if (stackBeingAplied.getUseAnimation() == UseAnim.EAT) {
			level.playSound(null, applyingToEntity.getX(), applyingToEntity.getY(), applyingToEntity.getZ(), applyingToEntity.getEatingSound(stackBeingAplied),
					applyingToEntity.getSoundSource(), 0.5F + 0.5F * level.random.nextInt(2),
					(level.random.nextFloat() - level.random.nextFloat()) * 0.2F + 1.0F);
		}
	}

private boolean shouldTriggerItemUseEffects() {
		if (remainingApplyTime < 2) {
			return false;
		}
		int applyTimePassed = stackBeingAplied.getUseDuration(applyingToEntity) - remainingApplyTime;
		int effectDelay = (int) (stackBeingAplied.getUseDuration(applyingToEntity) * 0.21875F);
		boolean canStartTriggering = applyTimePassed > effectDelay;
		return canStartTriggering && remainingApplyTime % 4 == 0;
	}

@Override
    protected void tick(E entity) {
        var treePos = BrainUtil.getMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get());
        if (NearestTreeSensor.isLog(entity.level(), treePos)) {
            BrainUtil.setMemory(entity, MemoryModuleType.LOOK_TARGET, new BlockPosTracker(treePos));
            this.breakingTime++;
            entity.swing(InteractionHand.MAIN_HAND, true);
            int i = (int) ((float) this.breakingTime / 160.0F * 10.0F);
            if (this.breakingTime % 20 == 0) {
                entity.playSound(SoundEvents.WOOD_HIT, 1, 1);
                entity.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1, 0.5F);
            }
            if (i != this.previousBreakProgress) {
                entity.level().destroyBlockProgress(entity.getId(), treePos, i);
                this.previousBreakProgress = i;
            }
            if (this.breakingTime == 160) {
                entity.playSound(SoundEvents.WOOD_BREAK, 1, 1);
                List<BlockPos> stump = new ArrayList<>(List.of());
                this.addAllStump(treePos, entity.level(), stump);
                this.fellTree(entity, treePos);
                var felled = BrainUtil.getMemory(entity, OccultismMemoryTypes.LAST_FELLED_TREE.get());
                if (felled != null) {
                    felled.addAll(stump);
                } else {
                    felled = stump;
                }
                BrainUtil.setMemory(entity, OccultismMemoryTypes.LAST_FELLED_TREE.get(), felled);
                this.doStop((ServerLevel) entity.level(), entity, entity.level().getGameTime());
                //we stop here (even though the above condition would save us) because sensor might reset last felled tree meanwhile
            }

        } else {
            //if the tree is gone, just stop and reset.
            this.doStop((ServerLevel) entity.level(), entity, entity.level().getGameTime());
        }
    }

protected void start(E entity) {
        this.breakingTime = 0;
        this.previousBreakProgress = -1;
    }

protected void stop(E entity) {
        BrainUtil.clearMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get());
    }

private void fellTree(E entity, BlockPos treePos) {
        Level level = entity.level();
        BlockPos base = treePos;
        Queue<BlockPos> blocks = new ArrayDeque<>();
        Set<BlockPos> visited = new HashSet<>();
        blocks.add(base);

        while (!blocks.isEmpty()) {

            BlockPos pos = blocks.remove();
            if (!visited.add(pos)) {
                continue;
            }

            if (!NearestTreeSensor.isLog(level, pos)) {
                continue;
            }

            for (Direction facing : Plane.HORIZONTAL) {
                BlockPos pos2 = pos.relative(facing);
                if (!visited.contains(pos2)) {
                    blocks.add(pos2);
                }
            }

            for (int x = 0; x < 3; x++) {
                for (int z = 0; z < 3; z++) {
                    BlockPos pos2 = pos.offset(-1 + x, 1, -1 + z);
                    if (!visited.contains(pos2)) {
                        blocks.add(pos2);
                    }
                }
            }

            level.destroyBlock(pos, true);
        }

    }

private void addAllStump(BlockPos pos, BlockGetter level, List<BlockPos> list) {
        for (Direction facing : Plane.HORIZONTAL) {
            BlockPos posR = pos.relative(facing);
            if (!list.contains(posR)
                    && level.getBlockState(posR).is(BlockTags.LOGS)
                    && level.getBlockState(posR.below()).is(BlockTags.DIRT)) {
                list.add(posR);
                this.addAllStump(posR, level, list);
            }
        }
    }

@Override
	public void tick() {
		double targetDistance = this.taskOwner.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
		boolean canSeeTarget = this.taskOwner.getSensing().hasLineOfSight(this.target);

		if (canSeeTarget) {
			++this.seeTime;
		}
		else {
			this.seeTime = 0;
		}

		if (!(targetDistance > (double)this.attackRadius * this.attackRadius) && this.seeTime >= 5) {
			this.taskOwner.getNavigation().stop();
		}
		else {
			this.taskOwner.getNavigation().moveTo(this.target, this.speedModifier);
		}

		this.taskOwner.getLookControl().setLookAt(this.target, 30f, 30f);

		if (--this.attackTime <= 0 && this.attackTime >= -preAttackTime) {
			if (!canSeeTarget)
				return;

			if (this.attackTime == 0)
				this.taskOwner.swing(InteractionHand.MAIN_HAND);

			if (this.attackTime == -preAttackTime) {
				float distMod = (float)Math.sqrt(targetDistance) / this.attackRadius;
				float distFactor = Mth.clamp(distMod, 0.1f, 1);

				this.taskOwner.performRangedAttack(this.target, distFactor);
				this.attackTime = Mth.floor(distMod * (float)(this.attackCooldownMax - this.attackCooldownMin) + (float)this.attackCooldownMin);
			}
		}
		else if (this.attackTime < 0) {
			this.attackTime = Mth.floor(Mth.lerp(Math.sqrt(targetDistance) / (double)this.attackRadius, this.attackCooldownMin, this.attackCooldownMax));
		}
	}

