	public static void onLivingAttackEvent(LivingAttackEvent event){
		// Players are immune to melee damage while charging
		if(event.getEntity() instanceof EntityPlayer && event.getSource().getTrueSource() instanceof EntityLivingBase){

			EntityPlayer player = (EntityPlayer)event.getEntity();
			EntityLivingBase attacker = (EntityLivingBase)event.getSource().getTrueSource();

			if(WizardData.get(player) != null){

				Integer chargeTime = WizardData.get(player).getVariable(CHARGE_TIME);

				if(chargeTime != null && chargeTime > 0
						&& player.getEntityBoundingBox().grow(EXTRA_HIT_MARGIN).intersects(attacker.getEntityBoundingBox())){
					event.setCanceled(true);
				}
			}
		}
	}

@SuppressWarnings("unchecked") // Again, we know it must be ok
	private void update(){

		if(this.selectedMinion != null && this.selectedMinion.get() == null) this.selectedMinion = null;

		prevMotionY = player.motionY;

		// This new system removes a lot of repetitive event handler code and inflexible data which had duplicate
		// functions, just for different enchantments.
		if(player.ticksExisted % IMBUEMENT_UPDATE_INTERVAL == 0) updateImbuedItems();
		updateContinuousSpellCasting();

		// Clean up expired recent spells every 60 ticks (1 second)
		if(player.ticksExisted % 60 == 0) {
			long currentTime = player.world.getTotalWorldTime();
			this.recentSpells.removeIf(entry -> (currentTime - entry.getValue()) >= Wizardry.settings.recentSpellExpiryTime);
		}

		this.spellData.forEach((k, v) -> this.spellData.put(k, k.update(player, v)));
		this.spellData.keySet().removeIf(k -> k.canPurge(player, this.spellData.get(k)));
	}

@Override
        public void tick(LivingEntity entity) {
            if(isCharge()) {
                if (!entity.level().isClientSide()) {
                    int temp = getTimer();
                    setTimer(temp - 1);
                    //Deal with rocket punch is valid
                    if (temp > 0) {
                        //Slightly enlarge player's hitbox
                        AABB collideBox = entity.getBoundingBox().inflate(0.75f, 0.75f, 0.75f);

                        //Collision Detection
                        List<LivingEntity> checks = entity.level().getEntitiesOfClass(LivingEntity.class, collideBox);
                        checks.remove(entity);

                        //If any mob is detected
                        if (!checks.isEmpty()) {
                            // spawn an watchEntity to simulate rocket punch effect
                            Wall_Watcher_Entity watchEntity = new Wall_Watcher_Entity(entity.level(), entity.blockPosition(), temp, effectiveChargeTime,
                                    knockbackSpeedIndex, damagePerEffectiveCharge, dx, dz,
                                    entity);

                            List<LivingEntity> impact = entity.level().getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(3.5f, 0.75f, 3.5f));
                            impact.remove(entity);

                            for (LivingEntity target : impact) {
                                // Deal damage
                                if (!target.isAlliedTo(entity)) {
                                    boolean flag = target.hurt(entity.damageSources().mobProjectile(entity, entity), damagePerEffectiveCharge * effectiveChargeTime);
                                    watchEntity.watch(target);
                                    if (flag) {
                                        target.playSound(SoundEvents.ANVIL_LAND, 1.5f, 0.8F);
                                    }

                                }
                            }
                            entity.level().addFreshEntity(watchEntity);

                            // Player stop moving and clear pocket punch status
                            entity.setDeltaMovement(0, 0, 0);
                            entity.hurtMarked = true;
                            setCharge(false);
                        }
                    }
                    if (entity.horizontalCollision || temp == 0) {
                        setCharge(false);
                    }
                }
            }
        }

@Override
    public void tick() {
        super.tick();
        if (!level().isClientSide()) {
            int temp = entityData.get(TIMER);
            if (watchedEntities != null && source != null) {
                if (!watchedEntities.isEmpty()) {
                    List<YUnchangedLivingEntity> entitiesRemoveFromWatchList = new ArrayList<>();
                    for (YUnchangedLivingEntity entity : watchedEntities) {
                        if (entity.livingEntity.horizontalCollision) {
                            if (!entity.livingEntity.isAlliedTo(source)) {
                                entity.livingEntity.invulnerableTime = 0;
                                float realDamageApplied = damagePerEffectiveCharge * effectiveChargeTime + 1;
                                boolean flag = entity.livingEntity.hurt(this.damageSources().mobProjectile(this, source), realDamageApplied);
                                if (flag) {
                                    entity.livingEntity.playSound(ModSounds.EXPLOSION.get(), 0.3F, 1);
                                    entity.livingEntity.addEffect(new MobEffectInstance(ModEffect.EFFECTSTUN.get(), 50));
                                }
                            }

                            entitiesRemoveFromWatchList.add(entity);
                        } else {
                            entity.setMotion(dx * knockbackSpeedIndex, dz * knockbackSpeedIndex);
                        }
                    }
                    for (YUnchangedLivingEntity remove : entitiesRemoveFromWatchList) {
                        removeFromWatchList(remove);
                    }
                    if (temp - 1 == 0) {
                        watchedEntities.clear();
                        remove(RemovalReason.DISCARDED);
                    } else entityData.set(TIMER, temp - 1);
                } else {
                    if (temp - 1 == 0) remove(RemovalReason.DISCARDED);
                    else entityData.set(TIMER, temp - 1);
                }
            } else {
                remove(RemovalReason.DISCARDED);
            }
        }
    }

@Override
    public void releaseUsing(ItemStack stack, Level level, LivingEntity entityLiving, int timeLeft) {
        if(entityLiving.isShiftKeyDown()) {
            if(!entityLiving.isFallFlying()) {
                int i = this.getUseDuration(stack) - timeLeft;
                int t = Mth.clamp(i, 1, 4);
                float f7 = entityLiving.getYRot();
                float f = entityLiving.getXRot();

                float f1 = -Mth.sin(f7 * ((float) Math.PI / 180F)) * Mth.cos(f * ((float) Math.PI / 180F));
                float f2 = -Mth.sin(f * ((float) Math.PI / 180F));
                float f3 = Mth.cos(f7 * ((float) Math.PI / 180F)) * Mth.cos(f * ((float) Math.PI / 180F));
                float f4 = Mth.sqrt(f1 * f1 + f2 * f2 + f3 * f3);
                float f5 = 3.0F * (t / 6.0F);
                f1 *= f5 / f4;
                f3 *= f5 / f4;
                entityLiving.push((double) f1, (double) 0, (double) f3);
                if (entityLiving.onGround()) {
                    float f6 = 1.1999999F;
                    entityLiving.move(MoverType.SELF, new Vec3(0.0D, (double) f6 / 2, 0.0D));
                }
                ChargeCapability.IChargeCapability ChargeCapability = ModCapabilities.getCapability(entityLiving, ModCapabilities.CHARGE_CAPABILITY);
                if (ChargeCapability != null) {
                    ChargeCapability.setCharge(true);
                    ChargeCapability.setTimer(t * 2);
                    ChargeCapability.seteffectiveChargeTime(t * 2);
                    ChargeCapability.setknockbackSpeedIndex(t * 2);
                    ChargeCapability.setdamagePerEffectiveCharge(0.6F);
                    ChargeCapability.setdx(f1 * 0.1F);
                    ChargeCapability.setdZ(f3 * 0.1F);
                }
                if (!level.isClientSide) {
                    ((Player) entityLiving).getCooldowns().addCooldown(this,CMCommonConfig.BulwarkOfTheFlame.cooldown);
                }
            }
        }
    }

public void watch(LivingEntity livingEntity) {
        if (livingEntity != null) {
            watchedEntities.add(new YUnchangedLivingEntity(livingEntity));
        }
    }

